    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]
    desc = instance.get("descriptors", {}) or {}
    vehicle_hint = instance.get("vehicle_count_hint", None)

    cust_set = set(customers)

    def route_load(route):
        s = 0
        for v in route:
            s += demands[v]
        return s

    def route_dist(route):
        if not route:
            return 0
        d = matrix[depot][route[0]] + matrix[route[-1]][depot]
        for i in range(len(route) - 1):
            d += matrix[route[i]][route[i + 1]]
        return d

    def total_dist(routes):
        s = 0
        for r in routes:
            s += route_dist(r)
        return s

    # Deterministic Clarke-Wright savings (with conservative capacity checks)
    alpha = 1.0
    if isinstance(desc, dict):
        # Slight bias to respect bottlenecks/high pressure by preferring demand-heavy nodes earlier in merges.
        # Kept small to avoid destabilizing feasibility.
        pressure = desc.get("demand_pressure", None)
        corridor = desc.get("corridor", None)
        if pressure is not None:
            try:
                if pressure > 0.98:
                    alpha = 1.15
                elif pressure < 0.95:
                    alpha = 0.95
            except:
                pass
        if corridor is not None:
